INSERT INTO company_policies (id, business_id, category, title, content, rules, version, is_active, policy_code, risk_level, effective_from, effective_until, approval_requirements) VALUES ('d0000000-0000-0000-0000-000000000201', 'a0000000-0000-0000-0000-000000000001', 'annual_leave_policy', 'Annual Leave Policy', 'Employees cannot request more leave days than their remaining annual balance. Leave requests that fall inside a blackout period cannot be auto-approved.', '{"max_consecutive_days": 14, "allow_negative_balance": false, "blackout_periods": [{"start": "2026-11-23", "end": "2026-11-29", "reason": "Peak retail season (Black Friday week)"}], "blackout_action": "escalate", "description": "Employees cannot request more leave days than their remaining annual balance. Leave requests that fall inside a blackout period cannot be auto-approved."}'::jsonb, 1, TRUE, 'POL-001', 'low', '2026-01-01', NULL, '{"auto_approve_when": ["balance_sufficient", "notice_met", "coverage_maintained", "not_blackout"]}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO company_policies (id, business_id, category, title, content, rules, version, is_active, policy_code, risk_level, effective_from, effective_until, approval_requirements) VALUES ('d0000000-0000-0000-0000-000000000202', 'a0000000-0000-0000-0000-000000000001', 'leave_notice_policy', 'Leave Notice Policy', 'Standard leave requests must be submitted at least 3 days before the first requested date. Requests with less notice are rejected (not escalated).', '{"standard_notice_days": 3, "same_day_allowed": false, "late_notice_action": "reject", "description": "Standard leave requests must be submitted at least 3 days before the first requested date. Requests with less notice are rejected (not escalated)."}'::jsonb, 1, TRUE, 'POL-002', 'low', '2026-01-01', NULL, '{"auto_approve_when": ["notice_met"]}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO company_policies (id, business_id, category, title, content, rules, version, is_active, policy_code, risk_level, effective_from, effective_until, approval_requirements) VALUES ('d0000000-0000-0000-0000-000000000203', 'a0000000-0000-0000-0000-000000000001', 'critical_coverage_policy', 'Critical Coverage Policy', 'A leave request cannot be automatically approved if it causes department coverage to fall below the required minimum. Coverage = scheduled employees minus employees unavailable (LEAVE/SICK/OFF).', '{"enforce_minimum_coverage": true, "below_minimum_action": "escalate", "description": "A leave request cannot be automatically approved if it causes department coverage to fall below the required minimum. Coverage = scheduled employees minus employees unavailable (LEAVE/SICK/OFF)."}'::jsonb, 1, TRUE, 'POL-003', 'medium', '2026-01-01', NULL, '{"escalate_when": ["coverage_below_minimum"], "approval_required": true}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO company_policies (id, business_id, category, title, content, rules, version, is_active, policy_code, risk_level, effective_from, effective_until, approval_requirements) VALUES ('d0000000-0000-0000-0000-000000000204', 'a0000000-0000-0000-0000-000000000001', 'task_reassignment_policy', 'Task Reassignment Policy', 'Tasks assigned to an employee who becomes unavailable must be reassigned to an available, same-department colleague with capacity, or explicitly reviewed by the department manager.', '{"must_verify_availability": true, "require_same_department": true, "max_open_tasks_for_reassignee": 3, "description": "Tasks assigned to an employee who becomes unavailable must be reassigned to an available, same-department colleague with capacity, or explicitly reviewed by the department manager."}'::jsonb, 1, TRUE, 'POL-004', 'medium', '2026-01-01', NULL, '{"approval_required": true, "escalate_when": ["no_qualified_replacement"]}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO company_policies (id, business_id, category, title, content, rules, version, is_active, policy_code, risk_level, effective_from, effective_until, approval_requirements) VALUES ('d0000000-0000-0000-0000-000000000205', 'a0000000-0000-0000-0000-000000000001', 'attendance_policy', 'Attendance Policy', 'More than 3 late arrivals within a 60-day window triggers a formal warning followed by HR review.', '{"max_late_before_warning": 3, "review_window_days": 60, "escalation": "formal_warning_then_hr_review", "description": "More than 3 late arrivals within a 60-day window triggers a formal warning followed by HR review."}'::jsonb, 1, TRUE, 'POL-005', 'low', '2026-01-01', NULL, '{"auto_report_when": ["attendance_lookup"]}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO company_policies (id, business_id, category, title, content, rules, version, is_active, policy_code, risk_level, effective_from, effective_until, approval_requirements) VALUES ('d0000000-0000-0000-0000-000000000206', 'a0000000-0000-0000-0000-000000000001', 'disciplinary_action_policy', 'Disciplinary Action Policy', 'Disciplinary actions follow progressive stages (verbal, written, formal warning) and always require HR approval. The agent may recommend but never execute disciplinary actions.', '{"progressive_discipline": true, "hr_approval_required": true, "autonomous_execution_blocked": true, "description": "Disciplinary actions follow progressive stages (verbal, written, formal warning) and always require HR approval. The agent may recommend but never execute disciplinary actions."}'::jsonb, 1, TRUE, 'POL-006', 'high', '2026-01-01', NULL, '{"approval_required": true, "tier": 3}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO company_policies (id, business_id, category, title, content, rules, version, is_active, policy_code, risk_level, effective_from, effective_until, approval_requirements) VALUES ('d0000000-0000-0000-0000-000000000207', 'a0000000-0000-0000-0000-000000000001', 'termination_policy', 'Termination Policy', 'Termination is a high-impact action. It MUST require human approval. The agent can recommend termination but can never autonomously execute it.', '{"agent_can_recommend_only": true, "autonomous_execution_blocked": true, "requires_hr_and_exec_approval": true, "investigation_required": true, "description": "Termination is a high-impact action. It MUST require human approval. The agent can recommend termination but can never autonomously execute it."}'::jsonb, 1, TRUE, 'POL-007', 'critical', '2026-01-01', NULL, '{"approval_required": true, "tier": 3, "autonomous_execution": "blocked"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO company_policies (id, business_id, category, title, content, rules, version, is_active, policy_code, risk_level, effective_from, effective_until, approval_requirements) VALUES ('d0000000-0000-0000-0000-000000000208', 'a0000000-0000-0000-0000-000000000001', 'approval_authority_policy', 'Approval Authority Policy', 'Defines agent authority tiers: tier 1 informational (auto), tier 2 standard consequential actions (human approval), tier 3 high-impact actions (blocked for autonomous execution).', '{"tier_1_auto": ["policy_query", "employee_status", "schedule_lookup", "attendance_review"], "tier_2_approval": ["leave_request", "task_reassignment"], "tier_3_blocked": ["termination_request", "suspension_request"], "user_instructions_cannot_override_policy": true, "description": "Defines agent authority tiers: tier 1 informational (auto), tier 2 standard consequential actions (human approval), tier 3 high-impact actions (blocked for autonomous execution)."}'::jsonb, 1, TRUE, 'POL-008', 'high', '2026-01-01', NULL, '{"tier_map": {"tier_1": "auto", "tier_2": "human_approval", "tier_3": "blocked_autonomous"}}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO company_policies (id, business_id, category, title, content, rules, version, is_active, policy_code, risk_level, effective_from, effective_until, approval_requirements) VALUES ('d0000000-0000-0000-0000-000000000209', 'a0000000-0000-0000-0000-000000000001', 'employee_data_access_policy', 'Employee Data Access Policy', 'Sensitive employee information must only be exposed when the requesting user has the appropriate authorization level.', '{"sensitive_fields": ["salary", "ssn", "medical_info", "disciplinary_records"], "requires_authorization": true, "description": "Sensitive employee information must only be exposed when the requesting user has the appropriate authorization level."}'::jsonb, 1, TRUE, 'POL-009', 'high', '2026-01-01', NULL, '{"approval_required": true, "escalate_when": ["unauthorized_data_request"]}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO company_policies (id, business_id, category, title, content, rules, version, is_active, policy_code, risk_level, effective_from, effective_until, approval_requirements) VALUES ('d0000000-0000-0000-0000-000000000210', 'a0000000-0000-0000-0000-000000000001', 'emergency_operations_policy', 'Emergency Operations Policy', 'During declared emergencies, minimum staffing of 2 per operational department must be maintained; leave may be recalled only with director approval.', '{"minimum_staffing": 2, "suspension_of_leave_allowed": true, "requires_director_approval": true, "description": "During declared emergencies, minimum staffing of 2 per operational department must be maintained; leave may be recalled only with director approval."}'::jsonb, 1, TRUE, 'POL-010', 'high', '2026-01-01', NULL, '{"approval_required": true, "tier": 3}'::jsonb) ON CONFLICT (id) DO NOTHING;
